private const val DEFAULT_ICON = "extension"

private const val REGULAR_ICON_STYLE = "regular"
private const val BOLD_ICON_STYLE = "bold"
private const val BOLD_STOCK_ICON_STYLE = "bold_stock"

/** RVX settings menu icons that cannot be thickened with an outline. */
private val FIXED_WEIGHT_RVX_ICONS = setOf("rvx_letters_bold", "revanced_colored")

@Suppress("unused")
val visualPreferencesIconsPatch = resourcePatch(
    VISUAL_PREFERENCES_ICONS_FOR_YOUTUBE_MUSIC.title,
    VISUAL_PREFERENCES_ICONS_FOR_YOUTUBE_MUSIC.summary,
) {
    compatibleWith(COMPATIBILITY_YOUTUBE_MUSIC)

    dependsOn(settingsPatch)

    val settingsMenuIconOption = stringOption(
        key = "settingsMenuIcon",
        default = DEFAULT_ICON,
        values = mapOf(
            "Extension" to DEFAULT_ICON,
            "Gear" to "gear",
            "YT alt" to "yt_alt",
            "ReVanced" to "revanced",
            "ReVanced Colored" to "revanced_colored",
            "RVX Letters" to "rvx_letters",
            "RVX Letters Bold" to "rvx_letters_bold",
        ),
        title = "RVX settings menu icon",
        description = "The icon for the RVX settings menu.",
        required = true,
    )

    val applyToAll by booleanOption(
        key = "applyToAll",
        default = true,
        title = "Apply to all settings menu",
        description = """
            Add icons to the native settings entry and the RVX settings screens.

            True (default): also add icons to individual settings inside RVX sub-screens.

            False: icons only on parent screens. No sub-setting icons, regardless of Icon style.

            Managers can remember false. Set this option to true to include sub-setting icons.
            """.trimIndentMultiline(),
        required = true
    )

    val iconStyleOption = stringOption(
        key = "iconStyle",
        default = REGULAR_ICON_STYLE,
        values = mapOf(
            "Regular" to REGULAR_ICON_STYLE,
            "Bold" to BOLD_ICON_STYLE,
            "Bold (stock size)" to BOLD_STOCK_ICON_STYLE,
        ),
        title = "Icon style",
        description = "The icon weight and size. Sub-setting icons require Apply to all settings menu = true.",
        required = true,
    )

    execute {
        // Check patch options first.
        val selectedIconType = settingsMenuIconOption
            .underBarOrThrow()
        val iconStyle = iconStyleOption
            .lowerCaseOrThrow()
            .let { style -> if (style.startsWith("bold (stock")) BOLD_STOCK_ICON_STYLE else style }
        val useBoldIcons = iconStyle == BOLD_ICON_STYLE || iconStyle == BOLD_STOCK_ICON_STYLE
        val useStockIconSize = iconStyle == BOLD_STOCK_ICON_STYLE

        if (useBoldIcons) {
            makeSettingsToolbarIconsBold()
        }

        if (applyToAll == true) {
            preferenceKey.putAll(rvxPreferenceKey)
        }

        // region copy shared resources

        copyResourcesWithRename("music/visual/icons", preferenceKey)

        preferenceKey.filterValues { it !in preferenceKey }.keys.forEach { title ->
            val drawable = "res/drawable/${title}_icon.xml"
            if (useBoldIcons) makeBold(drawable)
            if (useStockIconSize) setStockPreferenceIconGeometry(drawable)
        }

        // endregion

        // region copy RVX settings menu icon

        val fallbackIconPath = "music/visual/icons/extension"
        val iconPath = "music/visual/icons/$selectedIconType"
        val resourceGroup = ResourceGroup(
            "drawable",
            "revanced_settings_icon.xml"
        )

        try {
            copyResources(iconPath, resourceGroup)
        } catch (_: Exception) {
            // Ignore if resource copy fails

            // Add a fallback extended icon
            // It's needed if someone provides custom path to icon(s) folder
            // but custom branding icons for Extended setting are predefined,
            // so it won't copy custom branding icon
            // and will raise an error without fallback icon
            copyResources(fallbackIconPath, resourceGroup)
        }

        // Fixed-weight letter icons and the colored logo retain their authored strokes.
        val settingsIconDrawable = "res/drawable/revanced_settings_icon.xml"
        if (useBoldIcons && selectedIconType !in FIXED_WEIGHT_RVX_ICONS) {
            makeBold(settingsIconDrawable)
        }
        if (useStockIconSize) {
            setStockPreferenceIconGeometry(settingsIconDrawable)
            installStockPreferenceIconLayout(paddingStartDp = 24, titleInsetDp = 80)
        }

        installDynamicRvxSettingsIcon("revanced_settings_icon")

        // endregion

        updatePatchStatus(VISUAL_PREFERENCES_ICONS_FOR_YOUTUBE_MUSIC)
    }
}

/** Apply icons after all settings finalizers have added their preferences, before the searchable copy. */
internal fun ResourcePatchContext.applyVisualPreferenceIcons() {
    document(SETTINGS_HEADER_PATH).use { document ->
        document.doRecursively loop@{ node ->
            if (node !is Element) return@loop

            node.getAttributeNode("android:key")
                ?.textContent
                ?.removePrefix("@string/")
                ?.let { title ->
                    val drawableName = when (title) {
                        in preferenceKey.keys -> resolvePreferenceIcon(title)

                        // Add custom RVX settings menu icon
                        in intentKey -> intentIcon[title]
                        else -> null
                    }

                    drawableName?.let {
                        node.setAttribute("android:icon", "@drawable/$it")
                    }
                }

            var parent = node.parentNode
            while (parent is Element) {
                if (parent.getAttribute("android:key") == "revanced_settings") {
                    setStockPreferenceIconLayout(node)
                    break
                }
                parent = parent.parentNode
            }
        }
    }

    warnMissingPreferenceIcons(SETTINGS_HEADER_PATH)
}

private fun ResourcePatchContext.resolvePreferenceIcon(title: String): String {
    var iconTitle = title
    val visitedTitles = mutableSetOf<String>()

    while (true) {
        check(visitedTitles.add(iconTitle)) {
            "Missing icon or cyclic preference mapping for $title: $iconTitle"
        }

        val pathData = preferenceKey[iconTitle]
        check(pathData != null) {
            "Missing icon or cyclic preference mapping for $title: $iconTitle"
        }

        if (pathData.isIconPathData()) break

        iconTitle = pathData
    }

    check(get("res/drawable/${iconTitle}_icon.xml").exists()) {
        "Missing icon or cyclic preference mapping for $title: $iconTitle"
    }

    return "${iconTitle}_icon"
}

private fun String.isIconPathData(): Boolean {
    val command = firstOrNull()
    val coordinate = getOrNull(1) ?: return false

    return (command == 'M' || command == 'm') &&
        (coordinate.isWhitespace() || coordinate.isDigit() || coordinate in "+-.")
}

